/* Enciclopédia Cigana — correção visual móvel V17
   Somente interface: não modifica autenticação, dados, tiragens nem métodos.
   Incluir no index.html antes de </body>:
   <script src="./mobile-v17.js" defer></script>
*/
(() => {
  "use strict";
  const css = `
  html { -webkit-text-size-adjust:100%; text-size-adjust:100%; }
  body { overflow-x:hidden; }
  .wrap, .top, .panel, .appView, .hero, .hubCard, .textCard,
  .flowPanel, .flowStageCard, .metaCard { min-width:0; }
  .wrap { width:100%; }
  .hero h1, .sectionTitle, .brand, .detailTitle h2, .hubCard strong {
    overflow-wrap:break-word; word-break:normal; hyphens:auto;
  }
  button, input, select, textarea { max-width:100%; }
  .mobileMenuButton { display:none; }
  @media (max-width:700px) {
    .wrap { padding-left:14px; padding-right:14px; }
    header { position:relative; z-index:50; }
    .top { display:grid; grid-template-columns:minmax(0,1fr) auto;
      align-items:center; column-gap:10px; row-gap:8px; padding:12px 0; min-height:0; }
    .brand { margin:0; min-width:0; max-width:none; font-size:clamp(19px,5.6vw,24px);
      line-height:1.18; grid-column:1; }
    .mobileMenuButton { display:inline-flex; align-items:center; justify-content:center;
      gap:7px; grid-column:2; min-height:44px; border:1px solid var(--line);
      border-radius:14px; padding:9px 12px; background:#fff; color:var(--ink);
      font-size:15px; font-weight:700; cursor:pointer; }
    .top>.badge { display:none; }
    .accountMini { grid-column:1 / -1; width:100%; justify-content:flex-start;
      min-width:0; font-size:12px; gap:6px; }
    .accountMini span { min-width:0; overflow-wrap:anywhere; }
    .accountMini button { min-height:40px; }
    .navLinks { grid-column:1 / -1; width:100%; display:none!important; padding:10px;
      margin:0; border:1px solid var(--line); border-radius:18px; background:#fff;
      grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; }
    .navLinks.mobile-open { display:grid!important; }
    .navLinks button { display:block; width:100%; min-width:0; min-height:44px; padding:10px;
      text-align:center; white-space:normal; line-height:1.35; font-size:13px;
      overflow-wrap:break-word; }
    .navLinks button[style*="display:none"] { display:none!important; }
    .appView { padding-top:14px; }
    .hero { padding:12px 0 6px; }
    .hero h1 { font-size:clamp(27px,7.6vw,38px); line-height:1.14; }
    .hero p,.detailLead { font-size:15px; line-height:1.6; }
    .sectionTitle { font-size:clamp(25px,6vw,32px); line-height:1.2; }
    .notice { padding:14px; margin:14px 0 18px; font-size:14px; line-height:1.6; }
    .panel { padding:16px; border-radius:18px; margin-bottom:20px; }
    .hubGrid,.grid,.grid2,.metaGrid,.subjectGrid,.methodGuideGrid,.questionHub,
    .houseGrid,.contextGrid,.aiGrid,.positionGrid,.adminReadingCards {
      grid-template-columns:minmax(0,1fr); gap:12px;
    }
    .hubCard { padding:16px; border-radius:18px; }
    .hubCard strong { font-size:20px; line-height:1.25; }
    .hubCard span { font-size:14px; line-height:1.55; }
    .flowPanel { padding:15px; }
    .flowStageCard { padding:16px; }
    .flowSteps { grid-template-columns:repeat(5,minmax(125px,1fr)); gap:8px;
      overflow-x:auto; scrollbar-width:thin; }
    .flowStep { padding:12px; min-height:100px; }
    .flowStep h4 { font-size:16px; margin:8px 0; }
    .flowNav { flex-direction:column; }
    .flowNav button,.flowNav .goldBtn,.flowNav .ghostBtn { width:100%; min-height:44px; }
    .controls { align-items:stretch; }
    .controls input,.controls select,.controls button,
    .search,.select,.flowInput,.flowSelect,.flowTextarea { width:100%; min-width:0; }
    .cardTabs { position:static; max-width:100%; }
    .methodDiagram { max-width:100%; overflow-x:auto; }
    .adminModalCard { max-width:calc(100vw - 16px); }
    #pwaInstallBtn { bottom:max(12px,env(safe-area-inset-bottom)); }
    .footerNote { font-size:13px; line-height:1.6; }
  }
  @media (max-width:370px) {
    .navLinks { grid-template-columns:minmax(0,1fr); }
    .brand { font-size:19px; }
  }

  /* V18 — identidade visual editorial rosa, sem alterar lógica da aplicação */
  button { -webkit-appearance:none; appearance:none; }
  button.hubCard, button.hubCard strong, button.hubCard span {
    color:var(--ink);
    text-decoration:none;
    -webkit-text-fill-color:currentColor;
  }
  button.hubCard span { color:var(--muted); }
  button.hubCard:focus-visible, .mobileMenuButton:focus-visible,
  .navLinks button:focus-visible { outline:3px solid var(--rose); outline-offset:3px; }
  @media (max-width:700px) {
    :root { --shadow:0 8px 24px rgba(107,61,79,.075); }
    html { scroll-padding-top:95px; }
    body { background:linear-gradient(180deg,#fff9fc 0%,#fff3f8 46%,#fff 100%); }
    header { background:rgba(255,249,252,.98); border-bottom:1px solid #f0d9e2; }
    .top { column-gap:8px; padding-block:10px; }
    .brand { font-family:Georgia,serif; font-weight:700; letter-spacing:-.025em;
      font-size:clamp(18px,5vw,22px); overflow-wrap:normal; }
    .mobileMenuButton { background:var(--ink); color:#fff; border-color:var(--ink);
      border-radius:12px; box-shadow:0 4px 12px rgba(67,47,55,.12); }
    .navLinks { box-shadow:0 12px 24px rgba(67,47,55,.10); padding:12px; }
    .navLinks button { font-weight:600; color:var(--ink); background:#fff9fc;
      border-color:#efd6df; border-radius:12px; }
    .navLinks button.active { background:var(--ink);color:#fff; }
    .accountMini { font-size:12px; }
    .accountMini button { border-radius:12px; color:var(--ink); background:white; }
    .appView { padding-top:12px; }
    .hero { padding:16px 2px 4px; }
    .hero small, .kicker { font-size:10px; letter-spacing:.14em; }
    .hero h1 { font-family:Georgia,serif; font-weight:600;
      font-size:clamp(27px,7.2vw,36px); line-height:1.16;
      letter-spacing:-.028em; color:var(--ink); margin-bottom:12px; }
    .hero p,.detailLead { font-size:15px; line-height:1.64; max-width:65ch; }
    .notice { background:#fff1f7; border:1px solid #edcbda; color:#794c60;
      box-shadow:none; border-radius:16px; padding:14px 16px;
      font-size:14px; line-height:1.6; }
    .hubGrid { margin:16px 0 32px; gap:12px; }
    button.hubCard { position:relative; display:block; text-align:left; width:100%;
      background:#fff; border:1px solid #efd7e1; border-radius:18px;
      padding:20px 44px 18px 17px; min-height:112px; box-shadow:0 7px 20px rgba(96,51,70,.065);
      -webkit-tap-highlight-color:transparent; transform:none; }
    button.hubCard:active { background:#fff4f9; transform:scale(.995); }
    button.hubCard::after { content:"›"; position:absolute; right:15px; top:16px;
      width:23px; height:23px; display:grid; place-items:center;
      border-radius:50%; background:#fbe8f0; color:#9f5873;
      font:700 25px/1 Georgia,serif; }
    button.hubCard strong { display:block; font:600 21px/1.25 Georgia,serif;
      margin:0 0 8px; color:#693d50 !important; -webkit-text-fill-color:#693d50; }
    button.hubCard span { display:block; font:400 14px/1.58 Inter,Arial,sans-serif;
      color:#75616b !important; -webkit-text-fill-color:#75616b; }
    .panel { background:#fff; border-color:#efd7e1; box-shadow:var(--shadow); }
    .sectionTitle { font-family:Georgia,serif; color:var(--ink); }
    .flowStep, .flowStageCard, .textCard, .method, .areaCard, .metaCard {
      box-shadow:0 3px 14px rgba(96,51,70,.035); }
    .goldBtn { min-height:46px; }
    input, select, textarea { font-size:16px; } /* previne zoom de foco no iPhone */
    .flowNav button,.controls button,.smallBtn { min-height:44px; }
    .flowResult,.readingGuide,.comboNarrative { font-size:14px; line-height:1.65; }
    .footerNote { margin-top:25px; padding:10px 2px; }
    #pwaInstallBtn { max-width:calc(100vw - 24px);
      font-size:12px; padding:10px 12px; opacity:.94; }
    .cardTabs { top:0; position:relative; }
  }
  @media (prefers-reduced-motion:reduce) {
    .hubCard,.flowStep { transition:none!important; }
  }
  `;
  function init() {
    if (document.getElementById("mobileV17Styles")) return;
    const style = document.createElement("style");
    style.id = "mobileV17Styles";
    style.textContent = css;
    document.head.append(style);
    const nav = document.getElementById("mainNav");
    const top = nav && nav.parentElement;
    if (!nav || !top) return;
    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.id = "mobileMenuToggle";
    toggle.className = "mobileMenuButton";
    toggle.setAttribute("aria-controls", "mainNav");
    toggle.setAttribute("aria-expanded", "false");
    toggle.textContent = "☰ Menu";
    top.insertBefore(toggle, nav);
    function closeMenu() {
      nav.classList.remove("mobile-open");
      toggle.setAttribute("aria-expanded", "false");
      toggle.textContent = "☰ Menu";
    }
    toggle.addEventListener("click", () => {
      const open = nav.classList.toggle("mobile-open");
      toggle.setAttribute("aria-expanded", String(open));
      toggle.textContent = open ? "✕ Fechar" : "☰ Menu";
    });
    nav.addEventListener("click", event => {
      if (event.target.closest("button")) closeMenu();
    });
    window.addEventListener("keydown", event => {
      if (event.key === "Escape") closeMenu();
    });

    // V19: acesso ao manual sem substituir os métodos nem os dados existentes.
    const methodsPanel = document.querySelector("#view-metodos .panel");
    if (methodsPanel && !document.getElementById("methodGuideV19")) {
      const box = document.createElement("div");
      box.id = "methodGuideV19";
      box.style.cssText = "margin:12px 0 18px;padding:15px;background:#fff0f6;border:1px solid #e7bfd0;border-radius:16px;line-height:1.5";
      const link = document.createElement("a");
      link.href = "./guia-metodos-ilustrado.html";
      link.textContent = "📖 Abrir manual ilustrado: 34 tiragens passo a passo →";
      link.style.cssText = "display:block;color:#793f57;font-weight:700;text-decoration:none";
      box.append(link);
      const description = document.createElement("small");
      description.textContent = "Veja a disposição das cartas, cada posição e como interpretar.";
      description.style.cssText = "display:block;color:#8f687a;margin-top:6px";
      box.append(description);
      const first = methodsPanel.querySelector(".detailLead");
      if (first) first.insertAdjacentElement("afterend",box);
      else methodsPanel.prepend(box);
    }
    window.matchMedia("(min-width:701px)").addEventListener("change", event => {
      if (event.matches) closeMenu();
    });
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, {once:true});
  } else { init(); }
})();


/* V22: guias de execução inseridos sob os métodos existentes sem interferir nos eventos originais */
(function(){
 const DATA=[{"name":"Templo de Afrodite — 7 cartas","subtitle":"Compara pensamentos, sentimentos e intenções das duas pessoas.","positions":["1. Seus pensamentos.","2. Pensamentos dele(a).","3. Seus sentimentos.","4. Sentimentos dele(a).","5. Suas intenções.","6. Intenções dele(a).","7. Possível futuro."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 7 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Compare as cartas 1 e 2 para observar como cada pessoa pensa sobre a situação.","Compare as cartas 3 e 4 para analisar os sentimentos dos dois lados.","Compare as cartas 5 e 6 para compreender as intenções de cada pessoa.","Use a carta 7 como tendência de evolução ou possível futuro da relação.","Depois das comparações por pares, observe as combinações entre cartas próximas e integre tudo à pergunta realizada."],"note":""},{"name":"Taça do Amor — 7 cartas","subtitle":"Analisa a relação, cada pessoa, fatores do vínculo, futuro e conselho.","positions":["1. Como está a relação / como está meu relacionamento?","2. Como você se sente nessa relação?","3. Como ele(a) / o(a) parceiro(a) está nessa relação ou situação?","4. Variação A: o que houve com o relacionamento? Variação B: o que favorece no relacionamento?","5. O que não favorece no relacionamento.","6. Futuro próximo da relação.","7. Conselho final."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 7 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Comece pela carta 1 para compreender o estado geral do vínculo.","Compare as cartas 2 e 3 para observar como cada pessoa se encontra na relação.","Na carta 4, preserve a variação escolhida para a leitura: causa/acontecimento ou fator favorável.","Leia a carta 5 como aquilo que desfavorece ou dificulta o vínculo.","Finalize com a tendência da carta 6 e o conselho da carta 7."],"note":"A posição 4 aparece com duas funções diferentes nos materiais. As duas variações foram preservadas em vez de escolher apenas uma."},{"name":"Tiragem rápida de amor — 6 cartas","subtitle":"Energia do vínculo, consulente, parceiro, aprendizado, futuro próximo e conselho.","positions":["1. Energia do vínculo.","2. Consulente.","3. Parceiro(a).","4. Aprendizado.","5. Futuro próximo.","6. Conselho."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 6 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Use a carta 1 para estabelecer o clima atual do vínculo.","Compare as cartas 2 e 3 para observar os dois lados da relação.","A carta 4 mostra o aprendizado associado à situação.","A carta 5 apresenta a tendência de futuro próximo.","Feche a leitura com a orientação da carta 6."],"note":"As seis funções acima já faziam parte da descrição do método na V9 e foram mantidas sem acrescentar funções novas."},{"name":"Questão amorosa — 5 cartas","subtitle":"Sentimentos, afastamento, interesse, atitudes e possíveis desfechos.","positions":["1. Sentimentos envolvidos.","2. Motivos de afastamento.","3. Nível de interesse do(a) parceiro(a).","4. Atitudes que podem ser tomadas em relação à relação.","5. Possíveis desfechos para a questão amorosa."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 5 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia a carta 1 como base emocional da questão.","Relacione a carta 2 ao que provoca distância, retraimento ou dificuldade.","Use a carta 3 para avaliar o interesse dentro do contexto da pergunta.","A carta 4 orienta atitudes possíveis.","A carta 5 encerra com os desfechos ou a tendência da questão."],"note":""},{"name":"Jogada de 15 cartas","subtitle":"Leitura mais ampla do relacionamento.","positions":["1–3. Imagem que a outra pessoa tem do consulente.","4–6. Sentimentos.","7–9. Intenções — primeira parte.","10–12. Intenções — segunda parte; leia 7–12 em conjunto para planos, expectativas, ações, movimentos ou hesitações.","13–15. Passado e experiências da outra pessoa que influenciam o comportamento atual."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 15 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia cada linha como um bloco antes de cruzar informações entre linhas.","Diferencie claramente como a pessoa vê o consulente, o que sente e o que pretende.","As cartas 7 a 12 formam um conjunto maior para intenções e possíveis movimentos.","Use as cartas 13 a 15 para reconhecer influências passadas sobre o presente.","Finalize integrando os cinco blocos numa única narrativa."],"note":"O material não atribui uma função diferente a cada uma das 15 cartas. As posições são organizadas por blocos, e essa estrutura foi preservada."},{"name":"Intenções — 9 cartas","subtitle":"Três blocos: sentimentos, pensamentos e atitudes.","positions":["1–3. Sentimentos.","4–6. Pensamentos.","7–9. Atitudes."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 9 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia 1–3 em conjunto para formar o bloco de sentimentos.","Leia 4–6 em conjunto para formar o bloco de pensamentos.","Leia 7–9 em conjunto para formar o bloco de atitudes.","Compare os três blocos para perceber coerência ou diferença entre sentir, pensar e agir.","Integre o resultado à pergunta realizada."],"note":""},{"name":"Método de Confiança — 4 cartas","subtitle":"Aparência, essência, motivações e intenções.","positions":["1. O que essa pessoa aparenta ser.","2. Quem ela realmente é.","3. As motivações da pessoa.","4. As intenções da pessoa."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 4 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Compare a aparência indicada pela carta 1 com a essência mostrada pela carta 2.","A carta 3 ajuda a compreender o que move a pessoa.","A carta 4 mostra a intenção dentro do contexto consultado.","Observe contradições ou confirmações entre aparência, essência, motivação e intenção."],"note":""},{"name":"Situação — Ação — Solução","subtitle":"Situação atual, atitude indicada e provável consequência.","positions":["1. Situação — cenário atual.","2. Ação — o que pode ser feito.","3. Solução — o que tende a acontecer mediante as ações realizadas."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 3 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Comece pela carta 1 para definir o cenário.","Use a carta 2 como orientação prática ou movimento possível.","Leia a carta 3 como consequência/tendência vinculada à ação.","Una as três cartas em sequência: situação → atitude → possível solução."],"note":""},{"name":"Ex em Foco — 5 cartas","subtitle":"Sentimento, intenção de voltar, motivo do término, futuro e conselho.","positions":["1. O que ele(a) sente por mim?","2. Ele(a) tem intenção de voltar?","3. O que levou ao término?","4. Futuro se houver volta.","5. Conselho."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 5 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia as cartas 1 e 2 para separar sentimento de intenção.","A carta 3 contextualiza a causa do rompimento.","A carta 4 mostra a tendência caso haja retomada.","Finalize com a carta 5 como conselho para o consulente."],"note":""},{"name":"Tirada do Ex — 5 cartas","subtitle":"Sentimento, intenção, mudança de atitude, futuro e conselho.","positions":["1. O que sente por mim?","2. Tem intenções de voltar?","3. Mudou as atitudes?","4. Possível futuro.","5. Conselho."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 5 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Separe sentimento, intenção e mudança de comportamento nas três primeiras posições.","Use a carta 4 como tendência, não como destino imutável.","A carta 5 encerra com orientação ao consulente.","Observe se sentimento e intenção apontam para a mesma direção ou para movimentos diferentes."],"note":""},{"name":"Reconciliação — 5 cartas","subtitle":"Estado das duas pessoas, sentimento, expectativa e retorno.","positions":["1. Como a pessoa está?","2. Como você está?","3. Como a pessoa se sente em relação a você?","4. O que esperar dela?","5. Essa pessoa vai voltar?"],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 5 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Compare as cartas 1 e 2 para compreender o estado de cada lado.","A carta 3 aprofunda o sentimento da outra pessoa.","A carta 4 indica aquilo que pode ser esperado dela no contexto atual.","A carta 5 responde à tendência de retorno, sempre em conjunto com as posições anteriores."],"note":""},{"name":"Reconciliação — 4 cartas","subtitle":"Versão mais objetiva para reconciliação.","positions":["1. Como a pessoa se sente em relação a mim?","2. Como eu estou em relação à pessoa?","3. O que esperar da pessoa?","4. Futuro da relação."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 4 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Compare as cartas 1 e 2 para observar os dois lados emocionais.","A carta 3 mostra o que pode ser esperado da outra pessoa.","A carta 4 fecha com a tendência da relação.","Não leia a carta final isoladamente: relacione-a ao estado de ambos e ao comportamento esperado."],"note":""},{"name":"Ficar ou Partir — 6 cartas","subtitle":"Compara permanecer e partir e fecha com conselho.","positions":["1. Situação atual.","2. Por que ficar?","3. Por que partir?","4. Como me sentirei se ficar?","5. Como me sentirei se partir?","6. Conselho final."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 6 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Use a carta 1 para fixar o contexto atual.","Compare 2 e 3 para entender os dois caminhos.","Compare 4 e 5 para avaliar a experiência emocional de cada escolha.","A carta 6 orienta a decisão sem substituir a autonomia do consulente."],"note":""},{"name":"Novos Romances — 3 cartas","subtitle":"Passado amoroso, momento atual e tendência para novas relações.","positions":["1. Experiências e padrões anteriores que ainda influenciam a forma de se relacionar.","2. Momento amoroso atual — disponibilidade, contexto e energia presente.","3. Tendência amorosa — provável caminho para novos encontros ou desenvolvimento."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 3 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia a carta 1 como influência do passado sobre novas conexões.","A carta 2 mostra o estado atual e funciona como ponte da leitura.","A carta 3 indica tendência para novos romances se as condições atuais continuarem.","Integre a sequência como passado influente → momento atual → tendência."],"note":""},{"name":"Passado, Presente e Futuro — 3 cartas","subtitle":"Antecedentes, situação atual e tendência.","positions":["1. Passado — acontecimentos, sentimentos, decisões ou circunstâncias anteriores que ajudaram a formar a situação atual.","2. Presente — energia central da situação e aquilo que precisa receber maior atenção agora.","3. Futuro — tendência de desenvolvimento se as condições atuais continuarem."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 3 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia a carta 1 como antecedente e origem do quadro.","Use a carta 2 como centro da leitura e ponte entre passado e futuro.","A carta 3 representa tendência, não um destino absolutamente imutável.","Una as três em uma narrativa temporal coerente."],"note":""},{"name":"Momento Certo — 5 cartas","subtitle":"Energia, influências, riscos, oportunidade e conselho.","positions":["1. Energia atual.","2. Influências externas.","3. Risco.","4. Oportunidade.","5. Conselho final."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 5 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Comece pela energia atual e pelas influências externas.","Compare risco e oportunidade antes de concluir.","A carta 5 deve ser lida como orientação final sobre o momento.","Use o conjunto para avaliar condições e timing, não como cronologia garantida."],"note":"A numeração foi mantida conforme a consolidação do método para organizar o esquema visual."},{"name":"Método de Esclarecimento — 5 cartas","subtitle":"Situação, percepção, ação, ponto cego e propósito.","positions":["1. Situação.","2. Como me vejo.","3. Como agir.","4. O que eu me recuso a ver.","5. Propósito."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 5 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["A carta 1 estabelece o tema central.","Compare a percepção de si (2) com o ponto cego (4).","A carta 3 indica a ação possível dentro da situação.","A carta 5 fecha a leitura com propósito ou direção.","Integre as cinco posições para transformar esclarecimento em orientação."],"note":""},{"name":"Método Geral — 8 cartas","subtitle":"Panorama geral das principais áreas da vida.","positions":["1. Sua energia / você.","2. Energia do financeiro.","3. Energia do amor / vida amorosa.","4. Energia do campo / ambiente familiar.","5. Energia da espiritualidade.","6. Obstáculo.","7. Conselho.","8. Tendência de futuro."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 8 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia primeiro as áreas 1 a 5 para formar o panorama.","Use a carta 6 para identificar o obstáculo principal.","A carta 7 orienta como lidar com o quadro.","A carta 8 mostra a tendência geral de continuidade.","Observe repetições de tema entre áreas antes de sintetizar."],"note":""},{"name":"Cruz Céltica — 10 cartas","subtitle":"Análise ampla de uma situação complexa.","positions":["1. Situação Atual — o que está acontecendo no momento.","2. Obstáculo — o que cruza ou desafia a situação.","3. Base / Raiz — a origem ou causa inconsciente.","4. Passado Recente — o que está ficando para trás.","5. Possível Futuro — o que pode acontecer em breve.","6. Futuro Próximo — o que está chegando.","7. O Consulente — como o consulente vê a si mesmo.","8. Ambiente Externo — como os outros veem a situação.","9. Esperanças e Medos — desejos e temores mais profundos.","10. Resultado Final — o desfecho mais provável."],"steps":["Embaralhe as cartas mantendo foco na situação a ser analisada.","Posicione a 1ª carta ao centro.","Coloque a 2ª carta cruzada sobre a primeira.","Posicione as cartas 3, 4, 5 e 6 formando uma cruz ao redor do centro.","Disponha as cartas 7, 8, 9 e 10 em coluna vertical à direita.","Leia as cartas em sequência numérica, integrando as mensagens ao final."],"reading":["Leia as cartas em sequência numérica e integre as mensagens ao final.","A carta 2 é o desafio que cruza a situação; não precisa ser tratada como algo apenas negativo.","Compare a carta 5 (possível futuro) com a carta 10 (resultado final).","A tiragem é indicada para situações complexas que exigem visão de vários ângulos."],"note":"No esquema, “1/2” representa a carta 2 cruzada sobre a carta 1."},{"name":"Porta da Riqueza — 7 cartas","subtitle":"Situação financeira, potencial, hábitos, mudança e resultado.","positions":["1. Onde estou hoje financeiramente.","2. Meu maior potencial financeiro.","3. O que devo parar de fazer.","4. O que devo começar a fazer.","5. Qual energia espiritual posso ativar para prosperar.","6. O que vai mudar nos próximos meses.","7. Resultado se seguir os conselhos."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 7 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Comece pelo diagnóstico da posição 1.","Use a carta 2 como potencial a desenvolver.","Compare 3 e 4 como movimento de retirada e construção de hábitos.","A carta 5 acrescenta a camada simbólica/espiritual do método.","Leia 6 como mudança e 7 como resultado condicionado às orientações."],"note":""},{"name":"Método Financeiro — 5 cartas","subtitle":"Caminho financeiro, bloqueios e áreas de foco.","positions":["1. Estou no caminho para ganhar o dinheiro desejado?","2. O que trava meu caminho / minha movimentação?","3. Áreas da vida para focar para ganhar dinheiro.","4. Por que estou na situação financeira atual?","5. O que faz eu deixar dinheiro para trás?"],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 5 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["A carta 1 mostra o caminho financeiro dentro da pergunta.","A carta 2 aponta o principal bloqueio ou trava.","A carta 3 direciona o foco para áreas relevantes.","A carta 4 ajuda a compreender a situação atual.","A carta 5 mostra o padrão que pode afastar ou fazer perder recursos."],"note":""},{"name":"Panorama Comercial — 8 cartas","subtitle":"Produto, mercado, público, dinheiro, futuro e conselho.","positions":["1. Meu produto.","2. Relação emocional com ele.","3. Como lido comercialmente.","4. Posicionamento no mercado.","5. Recepção do público.","6. Parte financeira.","7. Futuro do produto.","8. Conselho."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 8 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia 1 a 4 para entender produto, relação pessoal e posicionamento.","A carta 5 mostra a recepção do público e a 6, a dimensão financeira.","A carta 7 apresenta a tendência do produto.","A carta 8 encerra com orientação prática.","Integre especialmente mercado, público e financeiro antes de concluir."],"note":""},{"name":"Jogo dos Caminhos — 8 cartas","subtitle":"Compara duas opções utilizando os mesmos critérios.","positions":["Opção A — 1. O que favorece.","Opção A — 2. O que precisa ser trabalhado.","Opção A — 3. Perspectivas.","Opção A — 4. Conselho.","Opção B — 1. O que favorece.","Opção B — 2. O que precisa ser trabalhado.","Opção B — 3. Perspectivas.","Opção B — 4. Conselho."],"steps":["Defina com clareza as duas alternativas: Opção A e Opção B.","Embaralhe mantendo a decisão em mente.","Retire 4 cartas para a Opção A e 4 cartas para a Opção B.","Use os mesmos quatro critérios para os dois caminhos.","Compare os pares equivalentes e depois faça a síntese de cada alternativa."],"reading":["Defina claramente qual alternativa será A e qual será B antes de retirar as cartas.","Leia primeiro as quatro posições da Opção A e depois as quatro da Opção B.","Compare A1 com B1, A2 com B2, A3 com B3 e A4 com B4.","Finalize comparando cada caminho como um conjunto, sem transformar a leitura em escolha automática pelo consulente."],"note":""},{"name":"Paradoxo da Escolha — 6 cartas","subtitle":"Dois grupos de três cartas para comparar alternativas.","positions":["Opção A — três cartas lidas em conjunto.","Opção B — três cartas lidas em conjunto."],"steps":["Defina claramente a Opção A e a Opção B.","Embaralhe mantendo a escolha em mente.","Retire 3 cartas para a Opção A e 3 cartas para a Opção B.","Leia cada trio como um conjunto.","Compare os dois grupos, preservando a ausência de funções individuais específicas no método original."],"reading":["Leia as três cartas da Opção A como uma narrativa única.","Leia as três cartas da Opção B da mesma forma.","Compare os dois conjuntos sem atribuir funções individuais que não foram definidas no material.","Use a comparação para ampliar a compreensão das alternativas."],"note":"O material não atribui funções próprias às seis posições. Por fidelidade à fonte, o site não inventa significados individuais."},{"name":"Linha do Tempo — 5 cartas","subtitle":"Evolução temporal da situação.","positions":["1. Passado Distante — origens e raízes mais antigas da situação.","2. Passado Recente — o que aconteceu nos últimos 30 dias.","3. Momento Presente — a situação atual; carta central e mais importante.","4. Futuro Próximo — o que se desenrola nas próximas semanas.","5. Futuro Distante — perspectiva de médio a longo prazo."],"steps":["Embaralhe pensando na linha de tempo da situação.","Disponha 5 cartas em linha reta, da esquerda para a direita.","Leia 1 e 2 como raízes e antecedentes do quadro.","Centralize a leitura na carta 3, que mostra o agora.","Projete 4 e 5 como tendência de curto e médio prazo."],"reading":["Leia 1 e 2 como raízes e antecedentes do quadro.","Centralize a leitura na carta 3, que mostra o agora.","Projete 4 e 5 como tendências de curto e médio/longo prazo.","Use quando quiser entender a evolução de um processo, e não apenas um sim/não.","Registrar a data da tiragem ajuda a conferir a tendência posteriormente."],"note":""},{"name":"Ferradura do Destino — 7 cartas","subtitle":"Passado, presente, futuro, influências, obstáculos e resultado.","positions":["1. Passado Distante — raízes e influências do passado.","2. Passado Recente — eventos recentes que impactam a situação.","3. Presente — a situação atual do consulente.","4. Futuro Próximo — o que chegará nos próximos dias/semanas.","5. Influências Externas — pessoas e fatores externos que agem.","6. Obstáculos — o que deve ser superado ou evitado.","7. Resultado Final — o desfecho provável do caminho."],"steps":["Embaralhe pensando na situação que deseja acompanhar no tempo.","Disponha 7 cartas da esquerda para a direita formando um arco (ferradura).","Leia as posições 1 a 3 para entender o histórico da situação.","Analise as posições 4 a 6 para o que está chegando e o que atrapalha.","Encerre com a carta 7 para o desfecho provável do caminho."],"reading":["Leia as posições 1 a 3 para entender o histórico da situação.","Analise as posições 4 a 6 para o que está chegando e o que atrapalha.","Encerre com a carta 7 para o desfecho provável do caminho.","É especialmente útil para decisões que dependem de tempo e de terceiros.","Compare a carta 3 (presente) com a 7 (resultado) para medir a evolução."],"note":""},{"name":"Mesa Real / Grand Tableau — 36 cartas","subtitle":"Panorama completo utilizando as 36 cartas.","positions":["1. Casa 1 — Cavaleiro: notícias, movimento e chegadas.","2. Casa 2 — Trevo: pequenas sortes e oportunidades rápidas.","3. Casa 3 — Navio: viagens, distância e mudanças.","4. Casa 4 — Casa: família, lar e estabilidade.","5. Casa 5 — Árvore: saúde, raízes e karma.","6. Casa 6 — Nuvens: confusão, dúvidas e instabilidade.","7. Casa 7 — Serpente: traições, desvios e complicações.","8. Casa 8 — Caixão: fim de ciclo e transformação.","9. Casa 9 — Buquê: alegria, convites e presentes.","10. Casa 10 — Foice: cortes, decisões rápidas e rupturas.","11. Casa 11 — Chicote: discussões, repetições e desgaste.","12. Casa 12 — Pássaros: conversas, ansiedade e dupla ação.","13. Casa 13 — Criança: começos, ingenuidade e novidades.","14. Casa 14 — Raposa: trabalho, astúcia e cuidado com enganos.","15. Casa 15 — Urso: força, proteção e figuras de autoridade.","16. Casa 16 — Estrela: propósito, espiritualidade e clareza.","17. Casa 17 — Cegonha: mudanças e renovação.","18. Casa 18 — Cachorro / Cão: amizade, lealdade e apoio.","19. Casa 19 — Torre: instituições, isolamento e estrutura.","20. Casa 20 — Jardim: vida social, público e encontros.","21. Casa 21 — Montanha: bloqueios, atrasos e obstáculos.","22. Casa 22 — Caminhos: escolhas e decisões.","23. Casa 23 — Ratos: perdas, desgaste e roubo de energia.","24. Casa 24 — Coração: amor e sentimentos.","25. Casa 25 — Anel: compromissos, contratos e acordos.","26. Casa 26 — Livro: segredos, estudos e o que está oculto.","27. Casa 27 — Carta: documentos, mensagens e comunicados.","28. Casa 28 — Cavalheiro: consulente homem / homem da questão.","29. Casa 29 — Dama: consulente mulher / mulher da questão.","30. Casa 30 — Lírios: maturidade, paz e sexualidade.","31. Casa 31 — Sol: sucesso, vitalidade e realização.","32. Casa 32 — Lua: reconhecimento, emoções e intuição.","33. Casa 33 — Chave: soluções, aberturas e certezas.","34. Casa 34 — Peixes: dinheiro, fluxo e abundância.","35. Casa 35 — Âncora: estabilidade, trabalho firme e persistência.","36. Casa 36 — Cruz: provação, fé e destino."],"steps":["Embaralhe o baralho completo; a Mesa Real funciona como panorama amplo.","Distribua as 36 cartas em 4 linhas de 8 cartas e uma última linha com as cartas 33 a 36.","Localize a carta do consulente (Cavalheiro ou Dama, conforme a técnica utilizada) como um dos pontos de partida.","Leia as cartas vizinhas — acima, abaixo, lados e diagonais.","Observe em qual casa cada carta foi posicionada.","Finalize sintetizando os temas por áreas da vida."],"reading":["Localize a carta do consulente e use-a como ponto de partida.","Observe cartas acima, abaixo, aos lados e nas diagonais.","Considere a casa em que cada carta caiu, relacionando a carta sorteada ao tema daquela casa.","Sintetize por áreas da vida, como amor, trabalho, dinheiro, lar e saúde.","Reserve tempo para a leitura: é o método mais amplo entre os cadastrados."],"note":"Na Mesa Real, as 36 casas possuem significados próprios. A interpretação também depende da carta que ocupa cada casa e das relações de vizinhança."},{"name":"Os Espelhos — 3 cartas","subtitle":"Como você se vê, como é visto e sua essência.","positions":["1. Como eu me vejo.","2. Como me veem.","3. Minha verdadeira essência."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 3 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Compare a autoimagem da carta 1 com a percepção externa da carta 2.","Use a carta 3 como eixo para compreender a essência indicada pelo método.","Observe confirmações e contrastes entre as três posições."],"note":""},{"name":"A Árvore — 10 cartas","subtitle":"Passado, presente, potenciais futuros e frutos.","positions":["1–3. O que me sustenta no passado.","4–6. O que me define no presente.","7–9. Potenciais de futuro.","10. Frutos da jornada."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 10 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia 1–3 como raízes e sustentação do passado.","Leia 4–6 como tronco/presente e definição atual.","Leia 7–9 como potenciais que podem se desenvolver.","A carta 10 sintetiza os frutos da jornada.","Integre os quatro níveis como uma trajetória de crescimento."],"note":""},{"name":"Maiêutica — 9 cartas","subtitle":"Talentos, percepção, expressão e vocação.","positions":["1. O que penso que sei sobre meus talentos.","2. O que é apenas opinião ou ilusão.","3. O que precisa ser questionado.","4. O que surge quando me confronto.","5. O que os outros refletem.","6. O que nasce da visão interna + externa.","7. Talento essencial emergente.","8. Caminho para expressar o talento.","9. Vocação revelada."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 9 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Comece pelas três primeiras posições para questionar percepções prévias.","Use 4–6 para confrontar e integrar visão interna e externa.","Leia 7–9 como síntese: talento, expressão e vocação.","Evite reduzir uma única carta a uma definição fixa de carreira; leia o processo inteiro."],"note":""},{"name":"Metamorfose — 7 cartas","subtitle":"Mudança, perdas, ganhos, resultado e conselho.","positions":["1. Como era antes.","2. O que fez a mudança acontecer.","3. Como ocorre o processo.","4. O que se perde.","5. O que se ganha.","6. Resultado.","7. Conselho."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 7 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia 1–3 como origem e processo da transformação.","Compare 4 e 5 para compreender perdas e ganhos.","Use a carta 6 como resultado da mudança.","Finalize com a carta 7 como orientação para atravessar o processo."],"note":""},{"name":"Psique Emocional — 12 cartas","subtitle":"Mapa simbólico de estados e recursos emocionais.","positions":["1. Medo.","2. Culpa.","3. Vergonha.","4. Raiva.","5. Tristeza.","6. Apego.","7. Esperança.","8. Amor.","9. Perdão.","10. Gratidão.","11. Confiança.","12. Liberdade."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 12 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia cada carta de acordo com o estado ou recurso emocional da posição.","Observe quais temas se repetem ou se reforçam entre posições.","Compare estados difíceis com recursos de elaboração e fortalecimento.","Finalize com uma síntese simbólica do mapa emocional, sem tratar a tiragem como diagnóstico psicológico."],"note":"Este método é simbólico/oracular e não substitui avaliação ou cuidado psicológico profissional."},{"name":"Nó Energético — 3 cartas","subtitle":"Bloqueio simbólico, consequência e orientação.","positions":["1. Nó que me bloqueia.","2. Consequência.","3. Como desatar."],"steps":["Defina o tema e formule uma pergunta clara, mantendo apenas um foco principal.","Embaralhe o baralho mantendo a pergunta em mente.","Retire 3 cartas e disponha-as exatamente na ordem numerada do esquema.","Leia primeiro a função de cada posição e depois relacione as cartas vizinhas e o contexto da pergunta.","Finalize integrando o conjunto em uma resposta coerente, evitando interpretar as cartas como significados isolados."],"reading":["Leia a carta 1 como símbolo do bloqueio consultado.","A carta 2 mostra a consequência associada ao padrão.","A carta 3 oferece orientação simbólica para trabalhar ou desfazer o nó.","Interprete como linguagem oracular, não como prova factual de ação espiritual externa."],"note":"As associações espirituais deste método são simbólicas/oraculares e não constituem comprovação factual."},{"name":"Jogada de 9 cartas — visão ampliada","subtitle":"Quadro 3×3 para uma visão mais ampla.","positions":["As nove cartas formam um quadro 3×3. O material não atribui uma função individual diferente para cada posição."],"steps":["Defina uma pergunta ou tema claro.","Embaralhe mantendo o foco no tema.","Retire 9 cartas e disponha-as em um quadro 3×3.","Observe o conjunto antes de interpretar combinações e sequências.","Faça a síntese sem atribuir significados posicionais que não constam no método."],"reading":["Observe primeiro o quadro completo e os temas que se repetem.","Relacione cartas vizinhas e sequências sem criar funções fixas para casas não definidas.","Use o 3×3 para ampliar a visão da situação e construir uma narrativa integrada.","A pergunta, o contexto e a ordem das cartas continuam sendo fundamentais."],"note":"Por fidelidade ao material, o site não inventa significados individuais para as nove casas."},{"name":"Resposta Detalhada — 6 cartas + fundo do deck","subtitle":"Resposta ampliada em duas fileiras de três cartas; o fundo do deck acrescenta contexto.","positions":["1–3. Primeiro bloco de três cartas: leia a sequência em conjunto, da esquerda para a direita.","4–6. Segundo bloco de três cartas: aprofunde ou complemente o primeiro bloco, sem inventar funções fixas para cada casa.","Fundo do deck. Carta complementar retirada da base do monte restante; simboliza um tema subjacente, de acordo com a convenção adotada."],"steps":["Escreva uma pergunta objetiva e mantenha esse foco durante toda a leitura.","Embaralhe as 36 cartas e retire seis cartas sem repor nenhuma.","Coloque 1, 2 e 3 na primeira linha; logo abaixo coloque 4, 5 e 6, sempre da esquerda para a direita.","Sem mexer nas seis posições, observe a carta que ficou no fundo do monte restante. Mantenha-a separada do desenho, como complemento.","Leia a primeira fileira, depois a segunda, compare as colunas e só ao final acrescente o fundo do deck à síntese."],"reading":["Interprete 1–3 como primeiro bloco e 4–6 como segundo; procure conexões de cartas vizinhas.","Compare 1 com 4, 2 com 5, 3 com 6 apenas como relações visuais, caso sua escola use leitura por colunas.","O fundo do deck não substitui nenhuma das seis cartas nem comprova fatos; contextualiza a leitura.","A fonte desta variante não define significados individuais obrigatórios para cada uma das seis casas."],"note":"São seis cartas colocadas + uma carta complementar do fundo do deck; não apresente sete posições fixas."}];
 const norm=t=>String(t||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ").trim();
 const format=t=>String(t||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
 const render=(m)=>'<div class="v22-guide"><h3>📖 Como fazer esta tiragem</h3><p>'+format(m.subtitle)+'</p><ol>'+m.steps.map(x=>'<li>'+format(x)+'</li>').join("")+'</ol><h4>Significado das posições</h4><ul>'+m.positions.map(x=>'<li>'+format(x)+'</li>').join("")+'</ul><h4>Como interpretar</h4><ul>'+m.reading.map(x=>'<li>'+format(x)+'</li>').join("")+'</ul>'+(m.note?'<p class="v22-note">'+format(m.note)+'</p>':'')+'</div>';
 function getMethod(t){const n=norm(t);return DATA.find(m=>n.includes(norm(m.name).split(" cartas")[0])||n.includes(norm(m.name).split(" variante")[0]))||null;}
 const style=document.createElement("style");
 style.textContent='.v22-guide{margin:16px 0;padding:18px;background:#fff8fb;border:1px solid #e9c9d7;border-radius:16px;color:#644052;font-size:14px;line-height:1.6}.v22-guide h3,.v22-guide h4{color:#813f5e;font-family:Georgia,serif;margin:10px 0}.v22-guide ol,.v22-guide ul{padding-left:22px}.v22-guide li{margin:8px 0}.v22-note{background:#fff0f5;padding:10px;border-radius:10px}.v22-button{display:inline-block;margin:10px 0;color:#fff;background:#92516c;border-radius:12px;padding:10px 15px;text-decoration:none;font-weight:bold}';
 document.head.append(style);
 function addGuides(){
  let titles=document.querySelectorAll('#view-metodos summary,#view-metodos h3,#view-metodos h4,#view-metodos strong,#view-metodos b');
  for(const title of titles){
   if(title.children.length||title.closest(".v22-guide"))continue;
   const m=getMethod(title.textContent);
   if(!m)continue;
   let parent=title.closest('details')||title.closest('.methodGuideCard,.methodCard,.panel');
   if(!parent||parent.id==="view-metodos"||parent.querySelector(':scope > .v22-guide'))continue;
   if(parent.querySelector('.v22-guide'))continue;
   const guide=document.createElement("div");guide.innerHTML=render(m);parent.append(guide.firstElementChild);
  }
 }
 function gameGuide(){
   const view=document.getElementById("view-abrir-jogo")||document.getElementById("view-jogo");
   if(!view)return;
   const select=[...view.querySelectorAll("select")].find(el=>/m[eé]todo/i.test(el.labels?.[0]?.textContent||el.parentElement?.textContent?.slice(0,120)||"")||/m[eé]todo/i.test(el.id));
   if(!select)return;
   const selected=select.selectedOptions?.[0]?.textContent||"";
   const m=getMethod(selected); if(!m)return;
   let anchor=select.closest('.flowStageCard,.panel,.flowPanel')||select.parentElement;
   if(!anchor)return;
   let target=anchor.querySelector("#v22GameGuide");
   if(!target){target=document.createElement("div");target.id="v22GameGuide";anchor.append(target);}
   if(target.dataset.method===m.name)return;
   target.dataset.method=m.name;
   target.innerHTML=render(m);
 }
 let busy=false;
 function refresh(){if(busy)return;busy=true;try{addGuides();gameGuide();}finally{busy=false;}}
 document.addEventListener("change",e=>{if(e.target.matches("select"))queueMicrotask(refresh)},true);
 document.addEventListener("click",()=>queueMicrotask(refresh),true);
 let pending=false;
 const observer=new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;refresh()})}});
 observer.observe(document.body,{childList:true,subtree:true});
 refresh();
})();
